def main():
    n, t = map(int, input().split())
    a = list(map(int, input().split()))

    r = {}
    c = {}
    d1 = 0
    d2 = 0

    ans = -1
    for l in range(t):
        ai = a[l]
        i = (ai - 1) // n
        j = (ai - 1) % n

        if i not in r:
            r[i] = 0
        r[i] += 1
        if r[i] == n:
            ans = l + 1
            break

        if j not in c:
            c[j] = 0
        c[j] += 1
        if c[j] == n:
            ans = l + 1
            break

        if i == j:
            d1 += 1
            if d1 == n:
                ans = l + 1
                break

        if i + j == n - 1:
            d2 += 1
            if d2 == n:
                ans = l + 1
                break

    print(ans)
